// Size of the sparkline viewBox.
const (
	trendWidth  = 240
	trendHeight = 56
)

// index is the dashboard: one period (week, month or year) of a sport
// category, the yearly goal, a weekly trend and the latest activities.
func (s *server) index(w http.ResponseWriter, r *http.Request) {
	ctx := r.Context()
	count, err := s.Store.Count(ctx)
	if err != nil {
		s.serverError(w, "count activities", err)
		return
	}
	d := indexData{Count: count, Categories: sport.Categories}
	if s.Garmin != nil {
		st, err := s.Garmin.Status(ctx)
		if err != nil {
			s.Logger.Warn("garmin status", "err", err)
		}
		d.Garmin = &st
	}
	if count == 0 {
		s.render(w, r, "index.html", "index", d)
		return
	}
	if d.Today, err = s.today(ctx); err != nil {
		s.serverError(w, "today", err)
		return
	}
	var ok bool
	q := r.URL.Query()
	if d.Category, ok = sport.ByID(q.Get("cat")); !ok {
		d.Category, _ = sport.ByID(defaultCategory)
	}
	today := localDate(s.now())
	tomorrow := today.AddDate(0, 0, 1)
	base := categoryFilter(d.Category.ID)

	d.Period = dashboardPeriods[0].ID
	for _, p := range dashboardPeriods {
		if q.Get("p") == p.ID {
			d.Period = p.ID
		}
	}
	for _, p := range dashboardPeriods {
		d.Tabs = append(d.Tabs, periodTab{ID: p.ID, Label: p.Tab, Active: p.ID == d.Period})
		if p.ID != d.Period {
			continue
		}
		from := weekStart(today)
		switch p.ID {
		case "month":
			from = monthStart(today)
		case "year":
			from = yearStart(today.Year())
		}
		if d.Hero, err = s.periodSummary(ctx, p.Label, base, from, tomorrow); err != nil {
			s.serverError(w, "sum period", err)
			return
		}
	}
	if d.Goal, err = s.goalProgress(ctx, d.Category.ID, today.Year(), today); err != nil {
		s.serverError(w, "goal", err)
		return
	}
	if d.Trend, err = s.weeklyTrend(ctx, base, today); err != nil {
		s.serverError(w, "trend", err)
		return
	}
	recent, err := s.Store.List(ctx, store.ListFilter{Limit: recentTiles})
	if err != nil {
		s.serverError(w, "list activities", err)
		return
	}
	if d.Recent, err = s.tiles(ctx, recent); err != nil {
		s.serverError(w, "load tracks", err)
		return
	}
	s.render(w, r, "index.html", "index", d)
}

// weeklyTrend returns the distance of the last trendWeeks ISO weeks up to
// and including the current one.
func (s *server) weeklyTrend(ctx context.Context, base store.ListFilter, today time.Time) (trend, error) {
	first := weekStart(today).AddDate(0, 0, -7*(trendWeeks-1))
	buckets, err := s.Store.Aggregate(ctx, withRange(base, first, today.AddDate(0, 0, 1)), store.ByWeek)
	if err != nil {
		return trend{}, err
	}
	byKey := map[string]float64{}
	for _, b := range buckets {
		byKey[b.Key] = b.DistanceM / 1000
	}
	values := make([]float64, trendWeeks)
	maxKm, sum := 0.0, 0.0
	for i := range values {
		values[i] = byKey[isoWeekKey(first.AddDate(0, 0, 7*i))]
		maxKm = math.Max(maxKm, values[i])
		sum += values[i]
	}
	const gap = 4.0
	barW := (trendWidth - gap*(trendWeeks-1)) / trendWeeks
	t := trend{AvgKm: sum / trendWeeks}
	for i, v := range values {
		h := 2.0 // empty weeks stay visible as a baseline
		if maxKm > 0 && v > 0 {
			h = math.Max(h, v/maxKm*trendHeight)
		}
		_, week := first.AddDate(0, 0, 7*i).ISOWeek()
		t.Bars = append(t.Bars, trendBar{
			X: round1(float64(i) * (barW + gap)), Y: round1(trendHeight - h), W: round1(barW), H: round1(h),
			Title:   fmt.Sprintf("KW %d: %s km", week, km(v*1000)),
			Current: i == trendWeeks-1,
		})
	}
	return t, nil
}

// Goal ring geometry: radius and circumference of the progress circle in
// a 120×120 viewBox.
const (
	ringRadius = 52.0
	ringCenter = 60.0
)

// RingCircumference is the length of the progress circle.
func (g *GoalProgress) RingCircumference() string {
	return strconv.FormatFloat(round1(2*math.Pi*ringRadius), 'f', 1, 64)
}

// RingDash is the stroke-dasharray of the progress arc.
func (g *GoalProgress) RingDash() string {
	c := 2 * math.Pi * ringRadius
	l := c * g.Percent / 100
	return fmt.Sprintf("%.1f %.1f", l, c)
}

// ExpectedPoint is the position of the "target today" marker on the ring
// (clockwise from 12 o'clock).
func (g *GoalProgress) ExpectedPoint() (p struct{ X, Y float64 }) {
	frac := 0.0
	if g.GoalKm > 0 {
		frac = math.Min(1, g.ExpectedKm/float64(g.GoalKm))
	}
	a := 2 * math.Pi * frac
	p.X = round1(ringCenter + ringRadius*math.Sin(a))
	p.Y = round1(ringCenter - ringRadius*math.Cos(a))
	return p
}

