func (s *server) more(w http.ResponseWriter, r *http.Request) {
	count, err := s.Store.Count(r.Context())
	if err != nil {
		s.serverError(w, "count activities", err)
		return
	}
	s.render(w, r, "more.html", "more", moreData{Count: count})
}
